import gurobipy as gp
from gurobipy import GRB
stores = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10', 'S11']
customers = ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10', 'C11', 'C12']
demand = {'C1': 11, 'C2': 1148, 'C3': 54, 'C4': 833, 'C5': 154, 'C6': 551, 'C7': 7081, 'C8': 76, 'C9': 66, 'C10': 174, 'C11': 15, 'C12': 680}
supply = {'S1': 4, 'S2': 575, 'S3': 1504, 'S4': 178, 'S5': 228, 'S6': 50, 'S7': 3, 'S8': 6148, 'S9': 6, 'S10': 10673, 'S11': 174}
cost = {'S1': {'C1': 0.639144, 'C2': 49.718428, 'C3': 33.758577, 'C4': 1570.67311, 'C5': 1370.40955, 'C6': 57.353078, 'C7': 57.182995, 'C8': 54.920961, 'C9': 1143.68091, 'C10': 52.49127, 'C11': 606.44344, 'C12': 1192.46865}, 'S2': {'C1': 605.478637, 'C2': 64.535626, 'C3': 478.477903, 'C4': 887.048074, 'C5': 65.461112, 'C6': 71.936052, 'C7': 41.290154, 'C8': 70.360382, 'C9': 35.35893, 'C10': 1472.74819, 'C11': 0.600459, 'C12': 49.86854}, 'S3': {'C1': 1139.04401, 'C2': 4.785056, 'C3': 1805.62142, 'C4': 1302.89581, 'C5': 2437.32123, 'C6': 103.803686, 'C7': 774.655824, 'C8': 4.515988, 'C9': 879.704854, 'C10': 162.705567, 'C11': 1208.61348, 'C12': 110.186885}, 'S4': {'C1': 69.269899, 'C2': 2105.48539, 'C3': 869.682023, 'C4': 1494.89857, 'C5': 310.537662, 'C6': 98.154557, 'C7': 103.369185, 'C8': 1758.87838, 'C9': 97.285407, 'C10': 94.650409, 'C11': 1277.25145, 'C12': 21.63619}, 'S5': {'C1': 980.411426, 'C2': 899.310883, 'C3': 1183.03255, 'C4': 402.098616, 'C5': 81.788641, 'C6': 1115.68195, 'C7': 123.804279, 'C8': 1121.14687, 'C9': 0.002445, 'C10': 1009.64517, 'C11': 35.348018, 'C12': 1625.43463}, 'S6': {'C1': 1246.7825, 'C2': 2105.79667, 'C3': 1014.33932, 'C4': 1494.66814, 'C5': 362.017391, 'C6': 98.171424, 'C7': 2170.40587, 'C8': 97.731877, 'C9': 97.26834, 'C10': 1987.99078, 'C11': 70.943969, 'C12': 389.159804}, 'S7': {'C1': 57.108602, 'C2': 23.836169, 'C3': 78.10573, 'C4': 742.806811, 'C5': 1926.07968, 'C6': 454.378996, 'C7': 458.290144, 'C8': 465.930766, 'C9': 28.138607, 'C10': 524.615426, 'C11': 997.531784, 'C12': 104.477945}, 'S8': {'C1': 981.290861, 'C2': 120.9013, 'C3': 1625.82069, 'C4': 1267.82293, 'C5': 2569.64461, 'C6': 13.471812, 'C7': 815.152543, 'C8': 253.423496, 'C9': 43.765629, 'C10': 275.978413, 'C11': 1228.06989, 'C12': 103.48323}, 'S9': {'C1': 30.53278, 'C2': 1444.8595, 'C3': 173.554732, 'C4': 1307.39131, 'C5': 965.20123, 'C6': 1843.77695, 'C7': 1483.64088, 'C8': 85.3221, 'C9': 1353.50093, 'C10': 1485.91538, 'C11': 29.423791, 'C12': 26.61942}, 'S10': {'C1': 94.11094, 'C2': 1422.99713, 'C3': 1470.77691, 'C4': 1419.33823, 'C5': 38.945278, 'C6': 72.201129, 'C7': 2040.46059, 'C8': 1542.70256, 'C9': 1803.80017, 'C10': 72.943658, 'C11': 2181.45421, 'C12': 973.551555}, 'S11': {'C1': 1032.90738, 'C2': 166.301848, 'C3': 1620.47671, 'C4': 64.668341, 'C5': 2000.50917, 'C6': 0.002896, 'C7': 47.038371, 'C8': 52.992211, 'C9': 1115.63362, 'C10': 129.793382, 'C11': 1295.09784, 'C12': 2330.76821}}
for i in stores:
    if i not in cost:
        raise ValueError(f'Missing cost data for store {i}')
    for j in customers:
        if j not in cost[i]:
            raise ValueError(f'Missing cost data for store {i}, customer {j}')
for j in customers:
    if j not in demand:
        raise ValueError(f'Missing demand data for customer {j}')
for i in stores:
    if i not in supply:
        raise ValueError(f'Missing supply data for store {i}')
m = gp.Model('Walmart_Transportation')
x = m.addVars(stores, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[i][j] * x[i, j] for i in stores for j in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for i in stores)) == demand[j] for j in customers), name='')
m.addConstrs((gp.quicksum((x[i, j] for j in customers)) <= supply[i] for i in stores), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')